package com.vandorlabs.neoforge.trapdoor;

import com.vandorlabs.persistence.TrapdoorData;
import com.vandorlabs.render.DiagonalPanelContact;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;

/** Loaded-only released placement discovery. Install every member before publishing any observer. */
public final class NativeTrapdoorFormation {
 private NativeTrapdoorFormation(){}
 private static final Direction[] REGULAR={Direction.SOUTH,Direction.WEST,Direction.NORTH,Direction.EAST};
 private static final Direction[] DIAGONAL={Direction.DOWN,Direction.UP,Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST};
 private static int axis(BlockPos p,Direction face){return p.getX()*face.getStepX()+p.getY()*face.getStepY()+p.getZ()*face.getStepZ();}
 private static boolean permitted(NativeTrapdoorEntity root,BlockPos p,Player player,Direction side,ItemStack stack){return player==null||root.getLevel().mayInteract(player,p)&&player.mayUseItemAt(p,side,stack);}
 private static boolean samePlane(NativeTrapdoorEntity a,NativeTrapdoorEntity b){return a.facing().getAxis()==b.facing().getAxis()&&DiagonalPanelContact.samePlane(a.geometryPosition(),a.inverted(),b.inverted(),a.facing()!=b.facing(),b.position().getY()-a.position().getY(),axis(b.position().subtract(a.position()),a.facing().getOpposite()));}
 public static boolean compatible(NativeTrapdoorEntity a,NativeTrapdoorEntity b){if(a.diagonal()!=b.diagonal()||a.geometryPosition()!=b.geometryPosition())return false;if(!a.diagonal())return !a.cover()&&!b.cover();var delta=b.position().subtract(a.position());if(a.facing().getAxis()==b.facing().getAxis()&&(a.geometryPosition()==2?axis(delta,a.facing())!=0:a.position().getY()!=b.position().getY()||a.geometryPosition()==0&&axis(delta,a.facing())!=0))return true;return a.facing()==b.facing()&&a.inverted()==b.inverted()||samePlane(a,b);}
 private static NativeTrapdoorLifecycle.Loaded access(NativeTrapdoorEntity root){return new NativeTrapdoorLifecycle.Loaded(){public boolean loaded(BlockPos p){return NativeTrapdoorEntity.loaded(root.getLevel(),p);}public NativeTrapdoorLifecycle.Leaf leaf(BlockPos p){return NativeTrapdoorEntity.at(root.getLevel(),p);}};}
 private static void repair(NativeTrapdoorEntity root,Set<NativeTrapdoorEntity> changed){for(var leaf:NativeTrapdoorLifecycle.repair(root,access(root)))changed.add((NativeTrapdoorEntity)leaf);}
 private static void links(NativeTrapdoorEntity t,BlockPos partner,BlockPos square,List<BlockPos> assembly,double hinge,double travel,Direction basis,boolean reverse){var p=t.links();t.installLinks(new NativeTrapdoorLinks(partner,square,assembly,hinge,travel,basis,reverse,p.inverted(),p.channelSignal(),p.powerKnown(),p.lastPower()));}
 private static void motion(NativeTrapdoorEntity t,NativeTrapdoorEntity reference,boolean intoWall,boolean overSurface){var a=t.settings();var b=reference.settings();var d=a.choices();var r=b.choices();t.formationSettings(new NativeTrapdoorSettings(new TrapdoorData(d.texture,d.position,d.rawLayout,r.trigger,d.tileTexture,d.cover,r.sliding,intoWall?r.intoWall:d.intoWall,overSurface?r.overSurface:d.overSurface),a.channels(),a.facing(),a.hingeSide(),a.rotationFlipped(),a.diagonal()));}
 private static void channels(NativeTrapdoorEntity t,NativeTrapdoorEntity reference,Set<NativeTrapdoorEntity> changed){var a=t.settings();var next=reference.settings().channels();if(a.channels().equals(next))return;t.formationSettings(new NativeTrapdoorSettings(a.choices(),next,a.facing(),a.hingeSide(),a.rotationFlipped(),a.diagonal()));if(t.getLevel() instanceof net.minecraft.server.level.ServerLevel server){int maximum=0;for(int i=0;i<next.size();i++)maximum=Math.max(maximum,com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.level(server,t.position(),next.get(i)));t.setChannelLevel(maximum);}changed.add(t);NativeTrapdoorEntity.formationPower(t,changed);}
 private static void move(NativeTrapdoorEntity root,boolean value,Set<NativeTrapdoorEntity> changed){for(var tile:root.group()){tile.installOpen(value);changed.add(tile);}}
 private static void pair(NativeTrapdoorEntity a,NativeTrapdoorEntity b,Set<NativeTrapdoorEntity> changed){if(a.getLevel()==null||a.getLevel().isClientSide||a.getLevel()!=b.getLevel()||a.links().partner()!=null||b.links().partner()!=null||a.position().distSqr(b.position())!=1||!compatible(a,b))return;
  var delta=a.position().subtract(b.position());var direction=Direction.getNearest(delta.getX(),delta.getY(),delta.getZ());if(a.diagonal()){if(direction.getAxis()!=a.facing().getCounterClockWise().getAxis()&&direction.getAxis()!=(a.geometryPosition()==2?a.facing().getOpposite():Direction.UP).getAxis())return;}else if(a.position().getY()!=b.position().getY())return;
  var al=a.links();var bl=b.links();links(a,b.position(),al.square(),al.assembly(),al.hinge(),al.travel(),al.groupFacing(),a.diagonal()&&direction!=a.facing().getCounterClockWise());links(b,a.position(),bl.square(),bl.assembly(),bl.hinge(),bl.travel(),bl.groupFacing(),b.diagonal()&&direction.getOpposite()!=b.facing().getCounterClockWise());motion(a,b,true,!a.diagonal());channels(a,b,changed);if(!a.diagonal()){a.formationFacing(direction);b.formationFacing(direction.getOpposite());}changed.add(a);changed.add(b);move(a,b.open(),changed);NativeTrapdoorEntity.formationPower(a,changed);
 }
 private static List<BlockPos> square(NativeTrapdoorEntity root,BlockPos base){Direction across=root.diagonal()?root.facing().getCounterClockWise():Direction.EAST,along=root.diagonal()?(root.geometryPosition()==2?root.facing().getOpposite():Direction.UP):Direction.SOUTH;return List.of(base,base.relative(across),base.relative(along),base.relative(across).relative(along));}
 private static void complete(NativeTrapdoorEntity root,Player player,ItemStack stack,Set<NativeTrapdoorEntity> changed){if(root.getLevel()==null||root.getLevel().isClientSide||!root.diagonal()&&root.cover())return;repair(root,changed);if(assemblies(root,player,stack,changed)||root.links().square()!=null)return;
  Direction across=root.diagonal()?root.facing().getCounterClockWise():Direction.EAST,along=root.diagonal()?(root.geometryPosition()==2?root.facing().getOpposite():Direction.UP):Direction.SOUTH;
  for(int x=-1;x<=0;x++)for(int y=-1;y<=0;y++){var base=root.position().relative(across,x).relative(along,y);var cells=square(root,base);var leaves=new ArrayList<NativeTrapdoorEntity>();for(var cell:cells){var leaf=NativeTrapdoorEntity.at(root.getLevel(),cell);if(leaf==null)break;repair(leaf,changed);if(leaf.links().square()!=null||!compatible(root,leaf)||leaf.links().partner()!=null&&!cells.contains(leaf.links().partner())||!permitted(root,cell,player,Direction.UP,stack))break;leaves.add(leaf);}if(leaves.size()!=4)continue;
   var reference=leaves.getFirst();for(var leaf:leaves)if(leaf!=root&&leaf.links().partner()!=null){reference=leaf;break;}boolean alongX=reference.facing().getAxis()==Direction.Axis.X,opened=reference.open();
   for(var leaf:leaves){var p=leaf.links();motion(leaf,reference,root.diagonal(),!root.diagonal());links(leaf,null,base,p.assembly(),p.hinge(),p.travel(),root.diagonal()?root.facing():p.groupFacing(),p.reverse());channels(leaf,reference,changed);changed.add(leaf);}
   if(root.diagonal()||alongX){pair(leaves.get(1),leaves.get(0),changed);pair(leaves.get(3),leaves.get(2),changed);}else{pair(leaves.get(2),leaves.get(0),changed);pair(leaves.get(3),leaves.get(1),changed);}move(root,opened,changed);NativeTrapdoorEntity.formationPower(root,changed);return;
  }
 }
 private static boolean assemblies(NativeTrapdoorEntity root,Player player,ItemStack stack,Set<NativeTrapdoorEntity> changed){if(root.diagonal()&&root.geometryPosition()!=1&&patch(root,player,stack,changed))return true;var facing=root.facing();var across=root.diagonal()?facing.getClockWise():facing.getAxis()==Direction.Axis.X?Direction.EAST:Direction.SOUTH;var u=new BlockPos(across.getStepX(),across.getStepY(),across.getStepZ());var v=root.diagonal()?root.geometryPosition()==2?new BlockPos(facing.getOpposite().getStepX(),0,facing.getOpposite().getStepZ()):new BlockPos(0,1,0):new BlockPos(across.getClockWise().getStepX(),0,across.getClockWise().getStepZ());
  if(root.diagonal()){var stagger=root.geometryPosition()==2?v.offset(0,root.inverted()?-1:1,0):v.relative(root.inverted()?facing:facing.getOpposite());if(discover(root,player,stack,u,stagger,true,changed))return true;}return discover(root,player,stack,u,v,false,changed);
 }
 private static boolean patch(NativeTrapdoorEntity root,Player player,ItemStack stack,Set<NativeTrapdoorEntity> changed){var cells=new HashMap<BlockPos,NativeTrapdoorEntity>();var visited=new HashSet<BlockPos>();var pending=new ArrayDeque<BlockPos>();pending.add(root.position());int[] low={Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE},high={Integer.MIN_VALUE,Integer.MIN_VALUE,Integer.MIN_VALUE};
  while(!pending.isEmpty()){var at=pending.removeFirst();if(!visited.add(at)||!NativeTrapdoorEntity.loaded(root.getLevel(),at))continue;var leaf=NativeTrapdoorEntity.at(root.getLevel(),at);if(leaf==null||!leaf.diagonal()||!compatible(root,leaf))continue;if(!permitted(root,at,player,Direction.UP,stack))return false;cells.put(at.immutable(),leaf);if(cells.size()>64)return false;int[] p={at.getX(),at.getY(),at.getZ()};for(int a=0;a<3;a++){low[a]=Math.min(low[a],p[a]);high[a]=Math.max(high[a],p[a]);if(high[a]-low[a]>=8)return false;}for(int dy=-1;dy<=1;dy++)for(int dz=-1;dz<=1;dz++)for(int dx=-1;dx<=1;dx++)if(dx!=0||dy!=0||dz!=0)pending.add(at.offset(dx,dy,dz));}
  if(cells.size()<2)return false;var normal=root.facing();var along=root.geometryPosition()==2?normal.getOpposite():Direction.UP;var across=normal.getClockWise();int minCol=Integer.MAX_VALUE,maxCol=Integer.MIN_VALUE,minRow=Integer.MAX_VALUE,maxRow=Integer.MIN_VALUE;boolean original=true;for(var at:cells.keySet()){var delta=at.subtract(root.position());original&=root.geometryPosition()==2?delta.getY()==0:axis(delta,normal)==0;int col=axis(delta,across),row=axis(delta,along);minCol=Math.min(minCol,col);maxCol=Math.max(maxCol,col);minRow=Math.min(minRow,row);maxRow=Math.max(maxRow,row);}
  if(original&&maxCol-minCol<=1&&maxRow-minRow<=1&&cells.size()==(maxCol-minCol+1)*(maxRow-minRow+1)){for(var leaf:cells.values())if(!leaf.links().assembly().isEmpty())clearRelations(leaf,true,false,changed);return false;}
  var members=new ArrayList<>(cells.keySet());Collections.sort(members);var shared=List.copyOf(members);boolean linked=true;for(var leaf:cells.values())linked&=shared.equals(leaf.links().assembly());if(linked)return true;var reference=cells.get(members.getFirst());across=reference.facing().getClockWise();minCol=Integer.MAX_VALUE;maxCol=Integer.MIN_VALUE;for(var at:members){int col=axis(at,across);minCol=Math.min(minCol,col);maxCol=Math.max(maxCol,col);}int width=maxCol-minCol+1,split=(width+1)/2;boolean opened=reference.open();
  for(var at:members){var leaf=cells.get(at);int col=axis(at,across)-minCol;boolean highSide=col>=split;int distance=highSide?width-1-col:col;boolean reversed=leaf.facing().getClockWise()==across?highSide:!highSide;motion(leaf,reference,true,true);links(leaf,null,null,shared,reversed?1+distance-1D/16:-distance+1D/16,(highSide?width-split:split)-1D/16,leaf.links().groupFacing(),reversed);changed.add(leaf);}for(var leaf:cells.values())channels(leaf,reference,changed);move(root,opened,changed);NativeTrapdoorEntity.formationPower(root,changed);return true;
 }
 private static boolean discover(NativeTrapdoorEntity root,Player player,ItemStack stack,BlockPos u,BlockPos v,boolean stagger,Set<NativeTrapdoorEntity> changed){var cells=new HashMap<BlockPos,NativeTrapdoorEntity>();var pending=new ArrayDeque<BlockPos>();pending.add(BlockPos.ZERO);int minX=0,maxX=0,minY=0,maxY=0;
  while(!pending.isEmpty()){var coordinate=pending.removeFirst();if(cells.containsKey(coordinate))continue;if(Math.abs(coordinate.getX())>8||Math.abs(coordinate.getY())>8)return false;var at=root.position().offset(u.getX()*coordinate.getX()+v.getX()*coordinate.getY(),u.getY()*coordinate.getX()+v.getY()*coordinate.getY(),u.getZ()*coordinate.getX()+v.getZ()*coordinate.getY());if(!NativeTrapdoorEntity.loaded(root.getLevel(),at))continue;var leaf=NativeTrapdoorEntity.at(root.getLevel(),at);if(leaf==null||!compatible(root,leaf))continue;if(!permitted(root,at,player,Direction.UP,stack))return false;cells.put(coordinate,leaf);if(cells.size()>64)return false;minX=Math.min(minX,coordinate.getX());maxX=Math.max(maxX,coordinate.getX());minY=Math.min(minY,coordinate.getY());maxY=Math.max(maxY,coordinate.getY());pending.add(coordinate.east());pending.add(coordinate.west());pending.add(coordinate.above());pending.add(coordinate.below());}
  int width=maxX-minX+1,height=maxY-minY+1;if(stagger&&height<2||width>8||height>8||cells.size()!=width*height||cells.size()<2||!stagger&&width<=2&&height<=2)return false;var members=new ArrayList<BlockPos>();for(int row=minY;row<=maxY;row++)for(int col=minX;col<=maxX;col++)members.add(cells.get(new BlockPos(col,row,0)).position().immutable());var shared=List.copyOf(members);var reference=cells.get(new BlockPos(minX,minY,0));boolean opened=reference.open();int split=(width+1)/2;
  for(var entry:cells.entrySet()){var leaf=entry.getValue();int col=entry.getKey().getX()-minX;boolean high=col>=split;int distance=high?width-1-col:col;motion(leaf,reference,true,true);boolean reversed=leaf.links().reverse();double hinge;
   if(leaf.diagonal()){var localX=leaf.facing().getClockWise();reversed=localX.getStepX()==u.getX()&&localX.getStepY()==u.getY()&&localX.getStepZ()==u.getZ()?high:!high;hinge=reversed?1+distance-1D/16:-distance+1D/16;}else{var direction=Direction.getNearest(u.getX(),u.getY(),u.getZ());leaf.formationFacing(high?direction:direction.getOpposite());hinge=-distance+1D/16;}
   links(leaf,null,null,shared,hinge,(high?width-split:split)-1D/16,leaf.links().groupFacing(),reversed);changed.add(leaf);
  }for(var leaf:cells.values())channels(leaf,reference,changed);move(root,opened,changed);NativeTrapdoorEntity.formationPower(root,changed);return true;
 }
 public static void complete(NativeTrapdoorEntity root,Player player,ItemStack stack){Set<NativeTrapdoorEntity> changed=new LinkedHashSet<>();complete(root,player,stack,changed);NativeTrapdoorEntity.publishFormation(changed);}
 public static void placed(NativeTrapdoorEntity root,LivingEntity placer,ItemStack stack){if(root.getLevel()==null||root.getLevel().isClientSide||root.inert())return;Player player=placer instanceof Player p?p:null;Set<NativeTrapdoorEntity> changed=new LinkedHashSet<>();changed.add(root);for(var side:root.diagonal()?DIAGONAL:REGULAR){var other=NativeTrapdoorEntity.at(root.getLevel(),root.position().relative(side));if(other==null||other.links().partner()!=null||!compatible(root,other)||!permitted(root,other.position(),player,side,stack))continue;pair(root,other,changed);if(root.links().partner()!=null)break;}complete(root,player,stack,changed);NativeTrapdoorEntity.formationPower(root,changed);if(root.cover())move(root,true,changed);NativeTrapdoorEntity.publishFormation(changed);}
 public static void unpair(NativeTrapdoorEntity root,boolean removing){Set<NativeTrapdoorEntity> changed=new LinkedHashSet<>();clearRelations(root,true,true,changed);var mate=NativeTrapdoorLifecycle.mate(root,access(root));var p=root.links();root.installLinks(p.relations(null,p.square(),p.assembly()));changed.add(root);if(mate instanceof NativeTrapdoorEntity other){p=other.links();other.installLinks(p.relations(null,p.square(),p.assembly()));changed.add(other);NativeTrapdoorEntity.formationPower(other,changed);}if(removing)changed.remove(root);NativeTrapdoorEntity.publishFormation(changed);}
 private static void clearRelations(NativeTrapdoorEntity root,boolean assembly,boolean square,Set<NativeTrapdoorEntity> changed){var old=root.links();if(assembly&&!old.assembly().isEmpty())for(var at:old.assembly()){var leaf=NativeTrapdoorEntity.at(root.getLevel(),at);if(leaf!=null&&old.assembly().equals(leaf.links().assembly())){var p=leaf.links();leaf.installLinks(p.relations(p.partner(),p.square(),List.of()));changed.add(leaf);}}if(square&&old.square()!=null)for(var at:NativeTrapdoorLifecycle.squareCells(root)){var leaf=NativeTrapdoorEntity.at(root.getLevel(),at);if(leaf!=null&&old.square().equals(leaf.links().square())){var p=leaf.links();leaf.installLinks(p.relations(p.partner(),null,p.assembly()));changed.add(leaf);}}var p=root.links();root.installLinks(p.relations(p.partner(),square?null:p.square(),assembly?List.of():p.assembly()));changed.add(root);}
 public record Inheritance(NativeTrapdoorEntity reference,boolean hinge,boolean rotation,double clickedHinge){}
 public static Inheritance captureInheritance(BlockPlaceContext context,CompoundTag raw){if(context.getClickedFace().getAxis()!=Direction.Axis.Y)return null;var reference=NativeTrapdoorEntity.at(context.getLevel(),context.getClickedPos().relative(context.getClickedFace().getOpposite()));if(reference==null||!reference.diagonal())return null;double hinge=reference.trapdoorVisual()==null?0:reference.trapdoorVisual().pose().hinge;return new Inheritance(reference,(raw==null||!raw.contains("DiagonalHingeSide",Tag.TAG_INT))&&!reference.sliding()&&reference.geometryPosition()!=2&&hinge>0&&hinge<1,raw==null||!raw.contains("DiagonalRotationFlipped",Tag.TAG_BYTE),hinge);}
 private static void hinge(NativeTrapdoorEntity t,int value){var s=t.settings();t.formationSettings(new NativeTrapdoorSettings(s.choices(),s.channels(),s.facing(),value,s.rotationFlipped(),s.diagonal()));}
 public static void inherit(NativeTrapdoorEntity owner,Inheritance inheritance){if(inheritance==null||!owner.diagonal())return;var reference=inheritance.reference;Set<NativeTrapdoorEntity> changed=new LinkedHashSet<>();if(inheritance.hinge){hinge(reference,inheritance.clickedHinge<.5?1:2);double local=owner.facing()==reference.facing()?inheritance.clickedHinge:1-inheritance.clickedHinge;hinge(owner,local<.5?1:2);changed.add(reference);changed.add(owner);NativeTrapdoorEntity.publishFormation(changed);}if(inheritance.rotation&&!owner.sliding()&&!reference.sliding()&&owner.geometryPosition()!=2&&reference.geometryPosition()!=2){boolean a=owner.trapdoorVisual().pose().reverse^owner.inverted(),b=reference.trapdoorVisual().pose().reverse^reference.inverted();if(a!=b){var s=owner.settings();owner.formationSettings(new NativeTrapdoorSettings(s.choices(),s.channels(),s.facing(),s.hingeSide(),!s.rotationFlipped(),s.diagonal()));changed.add(owner);NativeTrapdoorEntity.publishFormation(changed);}}}
}
